class Solution {
    public String decodeCiphertext(String encodedText,int rows){
        int cols=encodedText.length()/rows;
        StringBuilder answer=new StringBuilder();
        for(int start=0;start<cols;start++)for(int row=0,col=start;row<rows&&col<cols;row++,col++)answer.append(encodedText.charAt(row*cols+col));
        while(answer.length()>0&&answer.charAt(answer.length()-1)==' ')answer.deleteCharAt(answer.length()-1);
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun decodeCiphertext(encodedText:String,rows:Int):String{
        val cols=encodedText.length/rows;
        val answer=StringBuilder();
        for(start in 0 until cols){
            var row=0;
            var col=start;
            while(row<rows&&col<cols){
                answer.append(encodedText[row*cols+col]);
                row++;
                col++
            }
        };
        return answer.toString().trimEnd()
    }
}

